/* Numeric values of D3D12 enumerations/constants and x64 structure layouts: the binary contract of the
 * root signature container and of the API surface that consumes it. */
#include "rs.h"

typedef struct { const char *name; long long got, want; } KV;
#define EV(x, want) { #x, (long long)(x), (long long)(want) }
static void run_table(const KV *t, size_t n, const char *grp) {
    size_t i;
    for (i = 0; i < n; i++) CHECKF(t[i].got == t[i].want, "%s %s = %lld, want %lld", grp, t[i].name, t[i].got, t[i].want);
}
#define TABLE_TEST(tname, ...) TEST(d3d12_rootsig_cpu_const_##tname) { static const KV t[] = { __VA_ARGS__ }; run_table(t, sizeof t / sizeof *t, #tname); }

