TEST(d3d12_rootsig_cpu_const_float_limits) {
    CHECK(D3D12_FLOAT32_MAX == 3.402823466e+38f);
    CHECK(D3D12_MIN_DEPTH == 0.0f); CHECK(D3D12_MAX_DEPTH == 1.0f);
}
TEST(d3d12_rootsig_cpu_const_serialized_layout_is_the_struct_layout) {
    /* the serialized parameter records and static sampler records are copies of the in-memory field order */
    RS0 *b = calloc(1, sizeof *b); RSBUF m; if (!b) return; rs0_init(b);
    rs0_sampler(b, 0x11, 0x22, D3D12_SHADER_VISIBILITY_PIXEL)->MipLODBias = 1.0f;
    rs0_done(b, 0); rs_model0(&b->d, &m);
    /* header 6 dwords, no parameters, sampler record at byte 24 */
    EXPECT_EQ(m.n, 6 + 13); EXPECT_EQ(m.w[4], 24);
    EXPECT_EQ(m.w[6 + 10], 0x11); EXPECT_EQ(m.w[6 + 11], 0x22); EXPECT_EQ(m.w[6 + 12], D3D12_SHADER_VISIBILITY_PIXEL);
    EXPECT_EQ(m.w[6 + 4], 0x3f800000u);
    free(b);
}
